class EngineModule12:
    """A processing engine module implementing the required interface."""

    def __init__(self):
        self._status = "ready"
        self._last_processed = None

    def process(self, data):
        """Process the given data and update the module status."""
        self._status = "processing"
        # Perform processing (store the last processed data for state tracking)
        self._last_processed = data
        self._status = "success"

        # Return a dictionary containing the status as expected by the tests
        return {
            "status": "success",
            "data": data
        }

    def get_status(self):
        """Return the current status of the engine module."""
        return self._status
